export function getVsApp(slug: string): VsApp | undefined {
  return VS_APPS.find((a) => a.slug === slug);
}

export function vsAppsByCategory(id: VsCategoryId): VsApp[] {
  return VS_APPS.filter((a) => a.category === id);
}
